using Arconist.Core;
using System.Text.Json;
using System.Security.Cryptography;
string root=args.Length>0?args[0]:".",output=args.Length>1?args[1]:"group-evidence";Directory.CreateDirectory(output);
int passed=0,failed=0;var outcomes=new List<object>();
void Check(bool ok,string why){if(!ok)throw new Exception(why);}
void Test(string name,Action body){try{body();passed++;outcomes.Add(new{name,status="PASS"});Console.WriteLine("PASS "+name);}catch(Exception e){failed++;outcomes.Add(new{name,status="FAIL",error=e.ToString()});Console.WriteLine("FAIL "+name+": "+e.Message);}}
string Load(string n)=>File.ReadAllText(Path.Combine(root,"reconstructed/godot/content",n));
const string control="native_timing_group.aff",reverse="native_reverse_scroll.aff",disabled="native_noinput_group.aff";
Kernel New(string n=reverse){var k=new Kernel(Chart.Parse(Load(n)));k.Frame(0);return k;}
void F(Kernel k,int e)=>k.Frame(e+3002);
void Anchor(Kernel k){k.Frame(3000);Check(!k.Timeline.MusicStarted,"strict equality");k.Frame(3002);Check(k.Timeline.EffectiveTime==0,"anchor");}
using var oracle=JsonDocument.Parse(File.ReadAllText(Path.Combine(root,"reference_traces/r010/native-groups.json")));var o=oracle.RootElement;
Test("three exact original fixture payloads and E036 control identity",()=>{foreach(string n in new[]{control,reverse,disabled})Check(File.ReadAllBytes(Path.Combine(root,"research_harness/fixtures",n)).SequenceEqual(File.ReadAllBytes(Path.Combine(root,"reconstructed/godot/content",n))),n);Check(File.ReadAllBytes(Path.Combine(root,"research_harness/fixtures/native_noinput_control.aff")).SequenceEqual(File.ReadAllBytes(Path.Combine(root,"research_harness/fixtures",control))),"E036 control=E029 control");});
Test("typed group identity own timing lists and source metadata",()=>{var c=Chart.Parse(Load(reverse));Check(c.TimingGroups.Count==2&&ReferenceEquals(c.Timings,c.TimingGroups[0].Timings)&&c.Timings.SequenceEqual(c.TimingGroups[0].Timings)&&c.Timings.Count==1,"default alias values/separate lists");Check(c.Taps.Select(t=>t.Group.Id).SequenceEqual(new[]{0,1})&&c.TimingGroups[1].SourceOrder==2&&c.Taps[1].Timing.Bpm==-60&&ReferenceEquals(c.Taps[1].Timing,c.TimingGroups[1].Timings[1]),"group/selected negative record");Check(c.Taps[1].Timing.RawBpmToken=="-60.00"&&c.Taps[1].Timing.RawBeatsToken=="4.00"&&c.Taps[0].SourceOrder<c.Taps[1].SourceOrder,"token/order");});
Test("requested metadata speed and three exact native scale stages",()=>{var k=New();Check((double)k.EffectiveSpeed==o.GetProperty("effectiveSpeed").GetDouble(),"effective");var actual=k.TimingGroups.SelectMany(g=>g.Records).Select(r=>(double)r.Scale);Check(actual.SequenceEqual(o.GetProperty("scales").EnumerateArray().Select(v=>v.GetDouble())),"scales");Check(k.TimingGroups[0].Records[0].StartBound==int.MinValue&&k.TimingGroups[1].Records[0].EndBound==1200&&k.TimingGroups[1].Records[1].EndBound==1001620,"native bounds");});
Test("selected timing pointer and group lifetimes independent of chart end",()=>{var k=New();Check(k.Chart.JudgmentUnits==2&&k.Chart.EndTime==1620&&k.Chart.TimingGroups[0].LifetimeEnd==int.MaxValue&&k.Chart.TimingGroups[1].LifetimeEnd==2700,"N/end/lifetime");Check(k.TimingGroups[1].Records[1].Source==k.Notes[1].Data.Timing,"record relationship");});
foreach(var name in new[]{control,reverse}){string n=name;Test("E029 intermediate depth query admission and recording "+n,()=>{
 var k=New(n);var rows=new List<object>();var callbacks=new List<object>();string? difference=null;
 try {
 Check(!k.Notes[0].Active&&k.Notes[1].Active,"preroll admission");Check(k.TimingGroups[0].QueryLow==-2&&k.TimingGroups[0].QueryHigh==-1&&k.TimingGroups[1].QueryLow==-1&&k.TimingGroups[1].QueryHigh==0,"native signed preroll queries");
 Check(k.Notes[0].PreDepth==-12134&&k.Notes[1].PreDepth==(n==control?-6067:-3640),"integer predepth");
 Anchor(k);foreach(var row in o.GetProperty("depths").EnumerateArray()){
 int e=row[0].GetInt32();F(k,e);var a=k.Notes[0];var b=k.Notes[1];rows.Add(new{e,depths=k.Notes.Select(t=>t.Depth),active=k.Notes.Select(t=>t.Active),queries=k.TimingGroups.Select(g=>new{g.Id,g.QueryLow,g.QueryHigh,g.Active,g.FrameOffset})});
 Check(a.Depth==row[1].GetInt32()&&b.Depth==row[n==control?2:3].GetInt32(),"depthE"+e);Check(a.Active&&b.Active,"retainedE"+e);
 Check(k.TimingGroups[1].QueryLow==0&&k.TimingGroups[1].QueryHigh==1,"group queryE"+e);Check(k.TimingGroups[0].QueryLow==(e>=1499?1:0)&&k.TimingGroups[0].QueryHigh==(e>=1300?2:1),"default queryE"+e);
 }
 int pointer=42;foreach(var expected in o.GetProperty("callbacks").EnumerateArray()){
 var note=k.Notes[expected[0].GetInt32()-1];k.Down(4502,pointer,note.Lane);Check(k.Candidates.SequenceEqual(new[]{note.Id})&&k.Contacts.Single().Id==pointer-42,"candidate/contact");
 Check(k.Pure==expected[0].GetInt32()&&k.Shining==k.Pure&&k.Combo==k.Pure&&k.Score==expected[1].GetInt32()&&(double)k.Health==expected[2].GetDouble(),"recorder"+pointer);
 callbacks.Add(new{k.Pure,k.Score,health=(double)k.Health,k.Combo,note.Id,note.Contact,k.Candidates,k.Classifications});k.Up(pointer++);Check(k.ContactCount==0,"UP cleanup");}
 Check(k.Far==0&&k.Lost==0&&k.Notes.All(t=>t.Consumed&&!t.Missed)&&!k.Finished&&k.Result==null,"native stop");
 }catch(Exception ex){difference=ex.Message;throw;}finally{File.WriteAllText(Path.Combine(output,n==control?"E029-control.json":"E029-reverse.json"),JsonSerializer.Serialize(new{authority="E029",firstDifference=difference,rows,callbacks,nativeCompletion=false},new JsonSerializerOptions{WriteIndented=true}));}
});}
Test("three original integrator f32 returns",()=>{var k=New();foreach(var row in o.GetProperty("integrator").EnumerateArray())Check((double)k.DepthAt(row[0].GetInt32(),1)==row[1].GetDouble(),"integrator"+row[0]);});
Test("separate endpoint indexes keys1 and0 without contamination",()=>{foreach(string n in new[]{control,reverse,disabled}){var k=New(n);Check(k.TimingGroups[0].Index.Single().Key==1&&k.TimingGroups[1].Index.Single().Key==0,"keys");Check(k.TimingGroups[0].Index[1].SequenceEqual(new[]{k.Notes[0].Id})&&k.TimingGroups[1].Index[0].SequenceEqual(new[]{k.Notes[1].Id}),"own map");}});
Test("retained reverse depth exceeds300 and1200 without new admission",()=>{var k=New();Anchor(k);F(k,1000);Check(k.Notes[1].Depth==404&&k.Notes[1].Active,"cross threshold");F(k,1200);Check(k.Notes[1].Depth==1213&&k.Notes[1].Active&&k.ContactCount==0,"retention");F(k,1500);k.Down(4502,99,2);Check(k.Pure==1,"judge retained");});
Test("reversal changes depth direction without reversing E",()=>{var k=New();Anchor(k);F(k,1199);int before=k.Notes[1].Depth;F(k,1200);int peak=k.Notes[1].Depth;F(k,1201);Check(before<peak&&k.Notes[1].Depth<peak&&k.Timeline.EffectiveTime==1201&&k.Timeline.StartRequestCount==1,"depth turn/shared running clock");});
Test("repeated bucket queries deduplicate active references",()=>{var k=New();Anchor(k);for(int i=0;i<20;i++)F(k,1200);F(k,1500);k.Down(4502,42,2);Check(k.Candidates.Count==1&&k.RecorderCalls==1,"unique admission");});
Test("consumed grouped tap guard survives fresh pointer identities",()=>{var k=New();Anchor(k);F(k,1500);k.Down(4502,42,2);k.Up(42);k.Down(4502,43,2);Check(k.Candidates.Count==1&&k.Classifications.Single().Outcome=="guard_consumed"&&k.RecorderCalls==1&&k.Pure==1&&k.Contacts.Single().Id==1,"guard not pointer reuse");});
foreach(bool noinput in new[]{false,true}){bool ni=noinput;Test("E036 paired lifecycle noinput="+ni,()=>{var k=New(ni?disabled:control);string? difference=null;var events=new List<object>();try{Anchor(k);F(k,1500);Check(k.Notes.All(t=>t.Active)&&k.Chart.JudgmentUnits==(ni?1:2),"runtime/index/N");foreach(int lane in new[]{2,5}){int pointer=lane+40;k.Down(4502,pointer,lane);events.Add(new{lane,k.Candidates,k.Pure,k.Score,health=(double)k.Health,contacts=k.Contacts.Select(c=>c.Id)});Check(k.ContactCount==1&&k.Contacts.Single().Id==(lane==2?0:1),"retained input even disabled");if(lane==2&&ni)Check(k.Candidates.Count==0&&k.Pure==0&&k.RecorderCalls==0,"disabled collection");k.Up(pointer);}
 foreach(int e in new[]{1501,1600,1601,1620}){F(k,e);Check(!k.Finished&&k.Lost==0,"expiry/completionE"+e);}F(k,1621);var r=k.Result!;Check(k.Finished&&r.Pure==(ni?1:2)&&r.Score==(ni?10000001:10000002)&&r.Health==80&&r.Category==3&&r.Lost==0&&r.RecordedLost==0,"native cached result");Check((double)k.Health==(ni?80.19999694824219:80.4000015258789),"exact live H");Check(ni?(!k.Notes[1].Consumed&&!k.Notes[1].Missed&&k.Notes[1].Active):(k.Notes[1].Consumed&&!k.Notes[1].Active),"disabled final state");
 }catch(Exception e){difference=e.Message;throw;}finally{File.WriteAllText(Path.Combine(output,ni?"E036-noinput.json":"E036-control.json"),JsonSerializer.Serialize(new{authority="E036",firstDifference=difference,events,k.Result,notes=k.Notes.Select(t=>new{t.Id,t.Active,t.Consumed,t.Missed,t.Contact,t.InputEnabled,t.TimingGroupId})},new JsonSerializerOptions{WriteIndented=true}));}});}
Test("noinput does not extend chart end but still sets group lifetime",()=>{string text=Load(disabled).Replace("(1500,1)","(5000,1)");var k=new Kernel(Chart.Parse(text));Check(k.Chart.EndTime==1620&&k.Chart.JudgmentUnits==1&&k.Chart.TimingGroups[1].LifetimeEnd==6200,"instruction-backed filtering; later-note schedule engineering");});
Test("disabled tap never records even on late frame",()=>{var k=New(disabled);Anchor(k);F(k,1500);k.Down(4502,42,2);k.Up(42);F(k,10000);Check(k.Lost==1&&!k.Notes[1].Missed&&!k.Notes[1].Consumed&&k.Result!.Lost==1,"only enabled unhit default lost");});
Test("missing enabled notes expire once and result usesN",()=>{var k=New();Anchor(k);F(k,1600);Check(k.Lost==0,"strict equal");F(k,1601);Check(k.Lost==2&&k.RecorderCalls==2,"expiry");F(k,1621);Check(k.Result!.Lost==2&&k.Result.RecordedLost==2&&k.Score==0,"result");});
foreach(string n in new[]{control,reverse,disabled,"grouped_practice.aff"}){string name=n;Test("complete reconstructed session and fresh replay "+name,()=>{for(int run=0;run<2;run++){var k=New(name);Anchor(k);int t=k.Notes[0].Start;for(int e=1;e<=t;e++)F(k,e);foreach(var note in k.Notes.Where(n=>n.InputEnabled)){k.Down(t+3002,note.Lane,note.Lane);k.Up(note.Lane);}F(k,k.Chart.EndTime+1);Check(k.Result!.Pure==k.Chart.JudgmentUnits&&k.Result.Lost==0&&k.ContactCount==0&&k.Result.Score==10000000+k.Chart.JudgmentUnits,"complete/fresh");}});}
foreach(int e in new[]{1100,1200,1201}){int at=e;Test("60second interruption preserves both depths atE"+at,()=>{var k=New();Anchor(k);F(k,at);var depths=k.Notes.Select(n=>n.Depth).ToArray();k.Pause(at+3002);k.Frame(at+63002);Check(k.Timeline.EffectiveTime==at&&k.Notes.Select(n=>n.Depth).SequenceEqual(depths)&&k.Pure==0,"frozen");k.Down(at+63002,99,2);Check(k.ContactCount==0,"paused gate");k.Resume(at+63002);k.Frame(64502);Check(k.Timeline.EffectiveTime==1500&&k.Pure==0,"no syntheticDOWN");k.Down(64502,42,5);k.Up(42);k.Down(64502,43,2);Check(k.Pure==2,"postresume");});}
Test("group lifetime does not defer completed session to2700",()=>{var k=New();Anchor(k);F(k,1500);k.Down(4502,42,5);k.Up(42);k.Down(4502,43,2);k.Up(43);F(k,1620);Check(!k.Finished&&k.TimingGroups[1].Active,"end equality");F(k,1621);Check(k.Finished&&k.TimingGroups[1].Active,"complete before group end");});
Test("unsupported braces attributes groups reverse and note types reject",()=>{
 string c=Load(control),r=Load(reverse);var invalid=new[]{c.Replace("};","}"),c.Replace("};",""),c+"};",c.Replace("timinggroup(){","timinggroup(){timinggroup(){"),c+c.Substring(c.IndexOf("timinggroup")),c.Replace("timinggroup()","timinggroup(foo)"),c.Replace("timinggroup()","timinggroup(noinput,foo)"),c.Replace("(1500,1)","hold(1000,2000,1)"),c.Replace("(1500,1)","arc(1000,2000,0.5,0.5,s,0.5,0.5,0,none,false)"),r.Replace("-60.00","-120.00"),r.Replace("(1500,1)","(1600,1)"),r.Replace("timinggroup()","timinggroup(noinput)"),r.Replace("120.00","-120.00"),c.Replace("60.00","0.00"),c.Replace("60.00","NaN"),c.Replace("timing(0,60.00,4.00);","timing(0,60.00,4.00);timing(0,60.00,4.00);"),c.Replace("    timing(0,60.00,4.00);", ""),c.Replace("(1500,1)","(600001,1)"),r.Replace("timing(1200,-60.00,4.00);","timing(1200,-60.00,4.00);timing(1300,60.00,4.00);")};
